import requests, os
from datetime import datetime
from urllib.parse import urlparse
from flask import request
from urllib import parse
from PIL import Image


def get_filename_from_url(url):
    return os.path.basename(urlparse(url).path)


def download(url, upload_dir, url_referer=None):
    try:
        if url_referer:
            response = requests.get(url, headers=dict(referer=url_referer))
        else:
            response = requests.get(url)
        file_name = get_filename_from_url(url)
        file_name = parse.unquote(file_name)  # decode utf-8
        file_name = prepend_date_time_to_string(file_name)
        with open(os.path.join(upload_dir, file_name), "wb") as file:
            file.write(response.content)
        return file_name
    except requests.exceptions.RequestException as e:
        return str(e)


def prepend_date_time_to_string(string):
    return datetime.now().strftime("%Y-%m-%d_%H-%M-%S-%f_") + string


# From: http://flask.pocoo.org/docs/0.12/patterns/fileuploads/#a-gentle-introduction
# Sample: allowed_extensions = set(['png', 'jpg', 'jpeg', 'gif', 'svg'])
def allowed_file(filename, allowed_extensions):
    return "." in filename and filename.rsplit(".", 1)[1].lower() in allowed_extensions


# From: https://stackoverflow.com/questions/38987/how-to-merge-two-python-dictionaries-in-a-single-expression/26853961#26853961
# Given two dicts, merge them into a new dict as a shallow copy.
def merge_two_dicts(x, y):
    z = x.copy()
    z.update(y)
    return z


# this is used for sql queries where direct input is required
# in sql statements, single quotes are escaped by doubling them up
def escape_for_sql(string):
    return string.replace("'", "''")


def request_wants_json():
    best = request.accept_mimetypes.best_match(["text/html", "application/json"])
    return (
        best == "application/json"
        and request.accept_mimetypes[best] > request.accept_mimetypes["text/html"]
    )


def check_if_any_one_of_the_given_tags_exist(art, tags):
    for art_tag in art["tags"]:
        for tag in tags:
            if art_tag["tag_name"] == tag:
                return True


def get_image_dims(path):
    try:
        with Image.open(path) as img:
            return img.size  # (width, height)
    except Exception:
        return (None, None)

import sqlite3, os, sys

from helpers import get_image_dims


def run(db_path):
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        tables = [
            r[0]
            for r in conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()
        ]

        # Step 1: art_image schema migration
        if "art_image" not in tables:
            conn.execute("BEGIN")

            conn.execute("""
                CREATE TABLE art_image (
                    id       INTEGER PRIMARY KEY,
                    art_id   INTEGER NOT NULL,
                    url      TEXT NOT NULL,
                    position INTEGER NOT NULL DEFAULT 0,
                    FOREIGN KEY(art_id) REFERENCES art(id) ON DELETE CASCADE
                )
            """)

            offset, batch = 0, 500
            while True:
                rows = conn.execute(
                    "SELECT id, image_url FROM art LIMIT ? OFFSET ?", (batch, offset)
                ).fetchall()
                if not rows:
                    break
                for row in rows:
                    for pos, url in enumerate(
                        u for u in (row["image_url"] or "").split(",") if u
                    ):
                        conn.execute(
                            "INSERT INTO art_image(art_id, url, position) VALUES(?,?,?)",
                            (row["id"], url, pos),
                        )
                offset += batch

            conn.execute("DROP VIEW IF EXISTS art_artist_view")
            conn.execute("ALTER TABLE art DROP COLUMN image_url")

            conn.execute("CREATE INDEX idx_art_artist_id    ON art(artist_id)")
            conn.execute("CREATE INDEX idx_art_tag_art_id   ON art_tag(art_id)")
            conn.execute("CREATE INDEX idx_art_tag_tag_id   ON art_tag(tag_id)")
            conn.execute("CREATE INDEX idx_art_image_art_id ON art_image(art_id)")

            conn.execute("COMMIT")
            print("Step 1 complete: art_image schema migration.")
        else:
            print("Step 1 already applied — skipping.")

        # Step 2: updated_at index
        indexes = {
            r[0]
            for r in conn.execute(
                "SELECT name FROM sqlite_master WHERE type='index'"
            ).fetchall()
        }
        if "idx_art_updated_at" not in indexes:
            conn.execute("BEGIN")
            conn.execute("CREATE INDEX idx_art_updated_at ON art(updated_at DESC)")
            conn.execute("COMMIT")
            print("Step 2 complete: added idx_art_updated_at.")
        else:
            print("Step 2 already applied — skipping.")

        # Step 3: width/height columns + backfill
        img_cols = {
            r[1] for r in conn.execute("PRAGMA table_info(art_image)").fetchall()
        }
        if "width" not in img_cols:
            conn.execute("BEGIN")
            conn.execute("ALTER TABLE art_image ADD COLUMN width  INTEGER")
            conn.execute("ALTER TABLE art_image ADD COLUMN height INTEGER")
            conn.execute("COMMIT")
            print("Step 3a complete: added width/height columns to art_image.")
        else:
            print("Step 3a already applied — skipping.")

        rows = conn.execute(
            "SELECT id, url FROM art_image WHERE width IS NULL"
        ).fetchall()
        if rows:
            images_dir = os.path.join(os.path.dirname(db_path), "static", "images")
            batch = []
            updated = 0
            for row in rows:
                path = os.path.join(images_dir, row[1])
                w, h = get_image_dims(path)
                if w is not None:
                    batch.append((w, h, row[0]))
                if len(batch) >= 500:
                    conn.execute("BEGIN")
                    for item in batch:
                        conn.execute(
                            "UPDATE art_image SET width=?, height=? WHERE id=?", item
                        )
                    conn.execute("COMMIT")
                    updated += len(batch)
                    batch = []
            if batch:
                conn.execute("BEGIN")
                for item in batch:
                    conn.execute(
                        "UPDATE art_image SET width=?, height=? WHERE id=?", item
                    )
                conn.execute("COMMIT")
                updated += len(batch)
            print(f"Step 3b complete: backfilled dims for {updated} images.")
        else:
            print("Step 3b: no NULL dims to backfill.")

    except Exception:
        try:
            conn.execute("ROLLBACK")
        except Exception:
            pass
        raise
    finally:
        conn.close()


if __name__ == "__main__":
    db_path = os.path.join(os.path.dirname(__file__), "store.db")
    if not os.path.exists(db_path):
        print(f"Database not found: {db_path}")
        sys.exit(1)
    run(db_path)
    print("Done.")

from flask import Flask, jsonify, render_template, request, redirect, g, flash
import helpers, sqlite3, json, os, re, scrapers
from werkzeug.utils import secure_filename
from dotenv import load_dotenv

load_dotenv()

UPLOAD_FOLDER = os.path.join(os.path.dirname(__file__), "static/images/")
ALLOWED_EXTENSIONS = {"png", "jpg", "jpeg", "gif", "svg"}

app = Flask(__name__)
app.secret_key = os.environ["SECRET_KEY"]
app.database = os.path.join(os.path.dirname(__file__), "store.db")
app.config["UPLOAD_FOLDER"] = UPLOAD_FOLDER
app.settings_database = os.path.join(os.path.dirname(__file__), "settings.json")


@app.route("/")
def index():
    g.db = connect_db()
    art = get_all_art_data(g.db, count=51)
    g.db.close()
    return render_template("index.html", art=art, layout=load_settings().get("layout"))


def get_all_art_data(db, sort_by=None, count=51, offset=0):
    order = (
        "ORDER BY a.title DESC" if sort_by == "title" else "ORDER BY a.updated_at DESC"
    )
    rows = db.execute(
        f"{_BASE_ART_SELECT} {order} LIMIT ? OFFSET ?", [count, offset]
    ).fetchall()
    art = [_row_to_art_dict(r) for r in rows]
    filtered_tags = load_settings().get("filtered_tags") or []
    if filtered_tags:
        art = [
            a
            for a in art
            if not helpers.check_if_any_one_of_the_given_tags_exist(a, filtered_tags)
        ]
    return art


