_BASE_ART_SELECT = """
    SELECT
        a.id,  a.title,  a.source,
        a.created_at  AS added_on,
        a.updated_at  AS last_updated_on,
        a.artist_id,
        ar.name       AS artist_name,
        ar.website    AS artist_website,
        img.image_urls,
        img.image_widths,
        img.image_heights,
        tgs.tag_ids,
        tgs.tag_names
    FROM art a
    LEFT JOIN artist ar ON a.artist_id = ar.id
    LEFT JOIN (
        SELECT art_id,
               GROUP_CONCAT(url)    AS image_urls,
               GROUP_CONCAT(width)  AS image_widths,
               GROUP_CONCAT(height) AS image_heights
        FROM (SELECT art_id, url, width, height FROM art_image ORDER BY art_id, position)
        GROUP BY art_id
    ) img ON a.id = img.art_id
    LEFT JOIN (
        SELECT at.art_id,
               GROUP_CONCAT(t.id)   AS tag_ids,
               GROUP_CONCAT(t.name) AS tag_names
        FROM art_tag at JOIN tag t ON at.tag_id = t.id
        GROUP BY at.art_id
    ) tgs ON a.id = tgs.art_id
"""


def _row_to_art_dict(row):
    tag_ids = row["tag_ids"].split(",") if row["tag_ids"] else []
    tag_names = row["tag_names"].split(",") if row["tag_names"] else []

    urls = row["image_urls"].split(",") if row["image_urls"] else []
    widths = (row["image_widths"] or "").split(",")
    heights = (row["image_heights"] or "").split(",")

    def _to_int(v):
        try:
            return int(v)
        except:
            return None

    image_dims = {
        url: {"width": _to_int(w), "height": _to_int(h)}
        for url, w, h in zip(urls, widths, heights)
    }

    return {
        "id": row["id"],
        "title": row["title"],
        "image_url": urls,
        "image_dims": image_dims,
        "source": row["source"],
        "added_on": row["added_on"],
        "artist_id": row["artist_id"],
        "artist_name": row["artist_name"],
        "artist_website": row["artist_website"],
        "last_updated_on": row["last_updated_on"],
        "tags": [
            {"tag_id": int(tid), "tag_name": tname}
            for tid, tname in zip(tag_ids, tag_names)
        ],
    }


def connect_db():
    conn = sqlite3.connect(app.database)
    conn.row_factory = sqlite3.Row
    return conn


class Settings:
    def __init__(self, file_path):
        self.file_path = file_path
        try:
            with open(file_path, "r") as json_file:
                self.data = json.load(json_file)
        except:
            with open(file_path, "w") as json_file:
                json_file.write("{}")
            with open(file_path, "r") as json_file:
                self.data = json.load(json_file)

    def get(self, key):
        return self.data.get(key)

    def set(self, key, value):
        self.data[key] = value

    def rem(self, key):
        del self.data[key]

    def save(self):
        with open(self.file_path, "w") as json_file:
            json_file.write(json.dumps(self.data, indent=4))


